<?php
require dirname(__DIR__,3).'/vendor/autoload.php';$app=require dirname(__DIR__,3).'/bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
$pmo=App\Models\User::where('system_role','pmo')->where('account_status','active')->where('must_change_password',false)->firstOrFail();$user=App\Models\User::where('system_role','user')->where('account_status','active')->where('must_change_password',false)->firstOrFail();$kernel=$app->make(Illuminate\Contracts\Http\Kernel::class);
$check=function($value,$label){if(!$value)throw new Exception($label);echo 'PASS '.$label.PHP_EOL;};
$get=function($uri,$actor,$json=false)use($app,$kernel){$app['auth']->forgetGuards();$app['auth']->guard('web')->setUser($actor);$r=Illuminate\Http\Request::create('http://127.0.0.1:8000'.$uri,'GET');$r->setUserResolver(fn()=>$actor);if($json)$r->headers->set('Accept','application/json');$app->instance('request',$r);return $kernel->handle($r);};
foreach(['tasks','team']as$tab){$response=$get('/monitoring?tab='.$tab.'&q=review',$pmo);$html=$response->getContent();$check($response->getStatusCode()===200 && str_contains($html,'data-current-monitoring-tab="'.$tab.'"') && str_contains($html,'name="tab" value="'.$tab.'"'),'PMO '.$tab.' tab renders and retains its form tab');$check(substr_count($html,'<h1>Monitoring</h1>')===1 && str_contains($html,'value="review"'),'Single monitoring heading and preserved search');$json=$get('/monitoring?tab='.$tab,$pmo,true);$data=json_decode($json->getContent(),true);$check($json->getStatusCode()===200 && isset($data[$tab==='tasks'?'tasks':'employees']),'Existing '.$tab.' data access retained');$check($get('/monitoring?tab='.$tab,$user)->getStatusCode()===403,'Ordinary user cannot access company-wide '.$tab.' monitoring');}
foreach(['task'=>'tasks','team'=>'team']as$old=>$tab){$response=$get('/pmo/'.$old.'-monitor?q=review&project_id=7',$pmo);$location=$response->headers->get('Location');parse_str(parse_url($location,PHP_URL_QUERY),$query);$check($response->isRedirect() && str_contains($location,'/monitoring?') && ($query['tab']??null)===$tab && ($query['q']??null)==='review' && ($query['project_id']??null)==='7','Legacy '.$old.' link redirects with filters');$check($get('/pmo/'.$old.'-monitor',$pmo,true)->getStatusCode()===200,'Legacy '.$old.' JSON endpoint remains available');}
$employee=App\Models\User::where('system_role','user')->where('account_status','active')->firstOrFail();
$details=$get('/pmo/team-monitor/employee/'.$employee->id,$pmo,true);$check($details->getStatusCode()===200,'Employee workload read endpoint retained');file_put_contents(__DIR__.'/monitoring-employee.json',$details->getContent());
$check($get('/monitoring?tab=invalid',$pmo)->getStatusCode()===404,'Unknown monitoring tab rejected');
echo "Read-only checks completed; no monitoring actions submitted.\n";
